//! Deterministic generator for the M0 smoke corpus.
//!
//! Five tiny PNGs are produced from analytic shapes with fixed 8x8
//! supersampled coverage in f64. The committed corpus under
//! `tests/fixtures/smoke/` was generated by this tool; `--check` re-generates
//! in memory and compares byte-for-byte against the files on disk.
//! Encoded bytes are pinned by the locked `png` crate version.

use std::path::PathBuf;

use clap::Parser;
use vice_bench::corpus::{CorpusFile, CorpusManifest, CORPUS_SCHEMA};
use vice_bench::hashing::sha256_hex;

#[derive(Parser)]
#[command(
    name = "gen-smoke",
    version,
    about = "Deterministically (re)generate the M0 smoke corpus"
)]
struct Cli {
    #[arg(long)]
    out: PathBuf,
    /// Compare regenerated bytes against existing files instead of writing.
    #[arg(long)]
    check: bool,
    /// Also write SMOKE_MANIFEST.toml next to the images.
    #[arg(long)]
    write_manifest: bool,
}

struct Img {
    name: &'static str,
    width: u32,
    height: u32,
    description: &'static str,
    bytes: Vec<u8>,
}

fn main() {
    std::process::exit(run());
}

fn run() -> i32 {
    let cli = Cli::parse();
    let images = build_images();

    if cli.check {
        // DIFFERENT and MISSING are DIFFERENT OUTCOMES and no longer share an
        // exit code. Both cold contexts found the conflation independently: a
        // step that never produced the images looks exactly like a step whose
        // images disagree, so "the smoke corpus reproduces" could not be
        // distinguished from "the smoke corpus was never written". One is a
        // reproducibility failure; the other is the instrument not having run.
        let mut differing = 0u32;
        let mut missing = 0u32;
        for img in &images {
            let p = cli.out.join(img.name);
            match std::fs::read(&p) {
                Ok(disk) if disk == img.bytes => println!("{}: OK", img.name),
                Ok(_) => {
                    println!("{}: DIFFERENT", img.name);
                    differing += 1;
                }
                Err(e) => {
                    println!("{}: MISSING ({e})", img.name);
                    missing += 1;
                }
            }
        }
        if missing > 0 {
            eprintln!(
                "error: {missing} of {} smoke images are MISSING; this is the instrument not                  having run, not a byte difference (exit 3)",
                images.len()
            );
            return 3;
        }
        if differing > 0 {
            eprintln!(
                "error: {differing} of {} smoke images DIFFER from the recorded bytes (exit 1)",
                images.len()
            );
            return 1;
        }
        println!("{} smoke images reproduce byte for byte", images.len());
        return 0;
    }

    if let Err(e) = std::fs::create_dir_all(&cli.out) {
        eprintln!("error: create {}: {e}", cli.out.display());
        return 2;
    }
    for img in &images {
        let p = cli.out.join(img.name);
        if let Err(e) = std::fs::write(&p, &img.bytes) {
            eprintln!("error: write {}: {e}", p.display());
            return 2;
        }
        println!(
            "{}  {}x{}  {} bytes  sha256={}",
            img.name,
            img.width,
            img.height,
            img.bytes.len(),
            sha256_hex(&img.bytes)
        );
    }
    if cli.write_manifest {
        let manifest = CorpusManifest {
            schema: CORPUS_SCHEMA.to_string(),
            files: images
                .iter()
                .map(|i| CorpusFile {
                    name: i.name.to_string(),
                    sha256: sha256_hex(&i.bytes),
                    width: i.width,
                    height: i.height,
                    description: i.description.to_string(),
                })
                .collect(),
        };
        let text = match toml::to_string_pretty(&manifest) {
            Ok(t) => t,
            Err(e) => {
                eprintln!("error: serialize manifest: {e}");
                return 2;
            }
        };
        let p = cli.out.join("SMOKE_MANIFEST.toml");
        if let Err(e) = std::fs::write(&p, text) {
            eprintln!("error: write {}: {e}", p.display());
            return 2;
        }
        println!("manifest: {}", p.display());
    }
    0
}

// ---------------------------------------------------------------------------
// Image definitions
// ---------------------------------------------------------------------------

fn build_images() -> Vec<Img> {
    vec![
        Img {
            name: "rect_32.png",
            width: 32,
            height: 32,
            description: "axis-aligned red rectangle on white, hard edges (no AA)",
            bytes: encode_rgb(32, 32, [255, 255, 255], [200, 32, 32], |u, v| {
                (8.0..24.0).contains(&u) && (10.0..22.0).contains(&v)
            }),
        },
        Img {
            name: "circle_64.png",
            width: 64,
            height: 64,
            description: "black disc r=24 on white, antialiased",
            bytes: encode_rgb(64, 64, [255, 255, 255], [0, 0, 0], |u, v| {
                let (dx, dy) = (u - 32.0, v - 32.0);
                dx * dx + dy * dy <= 24.0 * 24.0
            }),
        },
        Img {
            name: "ring_64.png",
            width: 64,
            height: 64,
            description: "navy annulus (hole topology) outer r=26 inner r=14 on white, antialiased",
            bytes: encode_rgb(64, 64, [255, 255, 255], [16, 32, 96], |u, v| {
                let (dx, dy) = (u - 32.0, v - 32.0);
                let d2 = dx * dx + dy * dy;
                (14.0 * 14.0..=26.0 * 26.0).contains(&d2)
            }),
        },
        Img {
            name: "triangle_128.png",
            width: 128,
            height: 128,
            description: "green triangle on white, antialiased slanted edges",
            bytes: encode_rgb(128, 128, [255, 255, 255], [24, 112, 56], tri_inside),
        },
        Img {
            name: "glyph_16.png",
            width: 16,
            height: 16,
            description: "opaque dark cross on fully transparent exterior (RGBA)",
            bytes: encode_rgba_on_transparent(16, 16, [32, 32, 32], |u, v| {
                ((6.0..10.0).contains(&u) && (2.0..14.0).contains(&v))
                    || ((2.0..14.0).contains(&u) && (6.0..10.0).contains(&v))
            }),
        },
    ]
}

fn tri_inside(u: f64, v: f64) -> bool {
    let side = |ax: f64, ay: f64, bx: f64, by: f64| (bx - ax) * (v - ay) - (by - ay) * (u - ax);
    let d1 = side(64.0, 12.0, 116.0, 108.0);
    let d2 = side(116.0, 108.0, 12.0, 108.0);
    let d3 = side(12.0, 108.0, 64.0, 12.0);
    (d1 >= 0.0 && d2 >= 0.0 && d3 >= 0.0) || (d1 <= 0.0 && d2 <= 0.0 && d3 <= 0.0)
}

// ---------------------------------------------------------------------------
// Rendering helpers (fixed 8x8 supersampling, deterministic f64)
// ---------------------------------------------------------------------------

fn coverage_map(w: u32, h: u32, inside: impl Fn(f64, f64) -> bool) -> Vec<f64> {
    const S: u32 = 8;
    let mut out = Vec::with_capacity((w as usize) * (h as usize));
    for y in 0..h {
        for x in 0..w {
            let mut cnt = 0u32;
            for sy in 0..S {
                for sx in 0..S {
                    let u = f64::from(x) + (f64::from(sx) + 0.5) / f64::from(S);
                    let v = f64::from(y) + (f64::from(sy) + 0.5) / f64::from(S);
                    if inside(u, v) {
                        cnt += 1;
                    }
                }
            }
            out.push(f64::from(cnt) / f64::from(S * S));
        }
    }
    out
}

fn encode_rgb(
    w: u32,
    h: u32,
    bg: [u8; 3],
    fg: [u8; 3],
    inside: impl Fn(f64, f64) -> bool,
) -> Vec<u8> {
    let cov = coverage_map(w, h, inside);
    let mut data = Vec::with_capacity(cov.len() * 3);
    for c in cov {
        for i in 0..3 {
            let v = f64::from(bg[i]) + (f64::from(fg[i]) - f64::from(bg[i])) * c;
            data.push(v.round() as u8);
        }
    }
    encode_png(w, h, png::ColorType::Rgb, &data)
}

fn encode_rgba_on_transparent(
    w: u32,
    h: u32,
    color: [u8; 3],
    inside: impl Fn(f64, f64) -> bool,
) -> Vec<u8> {
    let cov = coverage_map(w, h, inside);
    let mut data = Vec::with_capacity(cov.len() * 4);
    for c in cov {
        data.push(color[0]);
        data.push(color[1]);
        data.push(color[2]);
        data.push((c * 255.0).round() as u8);
    }
    encode_png(w, h, png::ColorType::Rgba, &data)
}

fn encode_png(w: u32, h: u32, color: png::ColorType, data: &[u8]) -> Vec<u8> {
    let mut buf = Vec::new();
    {
        let mut enc = png::Encoder::new(&mut buf, w, h);
        enc.set_color(color);
        enc.set_depth(png::BitDepth::Eight);
        let mut writer = enc.write_header().expect("png header");
        writer.write_image_data(data).expect("png data");
        writer.finish().expect("png finish");
    }
    buf
}
